"""ساخت فایل .env برای سرور آزمایشی (بدون Docker، مثلاً روی VPS ویندوزی).

اجرا از پوشه backend:
    python scripts/make_staging_env.py

فقط از کتابخانه استاندارد Python استفاده می‌کند؛ رمزها تصادفی ساخته می‌شوند.
فایل .env موجود را بازنویسی نمی‌کند.
"""

import base64
import os
import secrets
import sys
from pathlib import Path

ENV_FILE = Path(__file__).resolve().parents[1] / ".env"


def build() -> tuple[str, str, str]:
    db_password = secrets.token_hex(16)
    demo_password = "Rz" + secrets.token_hex(5)
    content = "\n".join(
        [
            "# generated by scripts/make_staging_env.py - do not commit",
            "RAZI_ENV=staging",
            f"RAZI_DATABASE_URL=postgresql+psycopg://valiasr:{db_password}@localhost:5432/valiasr",
            f"RAZI_JWT_SECRET={secrets.token_hex(32)}",
            f"RAZI_DATA_ENCRYPTION_KEY={base64.urlsafe_b64encode(os.urandom(32)).decode()}",
            f"RAZI_DEMO_PASSWORD={demo_password}",
            "",
        ]
    )
    return content, db_password, demo_password


def main() -> int:
    if ENV_FILE.exists():
        print(f"{ENV_FILE} از قبل وجود دارد؛ چیزی تغییر نکرد.")
        return 1
    content, db_password, demo_password = build()
    ENV_FILE.write_text(content, encoding="ascii")
    print(f"فایل {ENV_FILE} ساخته شد.\n")
    print("دستور ساخت کاربر پایگاه داده (در psql به عنوان postgres):")
    print(f"  CREATE USER valiasr WITH PASSWORD '{db_password}';")
    print("  CREATE DATABASE valiasr OWNER valiasr;\n")
    print(f"رمز ورود کاربران نمایشی 1001 تا 1005:  {demo_password}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
